template<class NeighborClass>
void ForceSNAP<NeighborClass>::compute(System* system, Binning* binning, Neighbor* neighbor_)
{

  if(comm_newton == false)
    Kokkos::abort("ForceSNAP requires 'newton on'");
  x = system->x;
