@contextmanager
def drx_viz_theme() -> PluginEnabler:
    current_state = alt.themes.active
    if context.theme == "dark":
        new_theme = "datarobot_dark"
    else:
        new_theme = "datarobot_light"
    try:
        yield alt.themes.enable(new_theme)
    finally:
        alt.themes.enable(current_state)


